  Experimental: '실험적 기능',
  'Browser tabs stay on this device. Terminals run on paired computers and use their session recovery.':
    '브라우저 탭은 이 기기에 저장됩니다. 터미널은 페어링된 컴퓨터에서 실행되며 해당 컴퓨터의 세션 복구 기능을 사용합니다.',
