  'Every 2 minutes': '2분마다',
  'When I refresh': '새로고침할 때',
  'Update widgets': '위젯 업데이트',
  'Task list': '작업 목록',
  'Working groups running tasks in a collapsed section. They return to the main list when they need input or finish. Pinned tasks stay visible.':
    '실행 중인 작업은 접힌 섹션의 작업 그룹으로 표시됩니다. 입력이 필요하거나 완료되면 기본 목록으로 돌아옵니다. 고정된 작업은 계속 표시됩니다.',
  'Default sort': '기본 정렬',
  'Working section': '작업 중 섹션',
  Snoozing: '다시 알림',
  'Enter 1–12 durations separated by commas, in menu order: m for minutes, h for hours, d for days or w for weeks. Existing snoozed threads keep their wake-up time.':
    '메뉴에 표시할 순서대로 쉼표로 구분해 1~12개의 시간을 입력하세요. m은 분, h는 시간, d는 일, w는 주를 뜻합니다. 다시 알림이 설정된 기존 스레드의 알림 시간은 유지됩니다.',
  Confirmations: '확인',
  'Archived threads can always be restored from Settings → Archived threads. Stopping pauses queued messages.':
    '보관된 스레드는 설정 → 보관된 스레드에서 언제든 복원할 수 있습니다. 중지하면 대기 중인 메시지가 일시 중지됩니다.',
  'Confirm before archiving a task': '작업 보관 전에 확인',
  'Confirm before stopping a running task': '실행 중인 작업 중지 전에 확인',
  'The merge method is preselected when merging and falls back to the forge’s default. Draft applies where the forge supports it.':
    '병합할 때 병합 방법이 미리 선택되며, 지원되지 않으면 코드 호스팅 서비스의 기본값을 사용합니다. 초안은 해당 서비스에서 지원하는 경우 적용됩니다.',
  'Merge method': '병합 방법',
  'Forge default': '코드 호스팅 서비스 기본값',
  Merge: '병합',
  Squash: '스쿼시 병합',
  Rebase: '리베이스',
  'Create pull requests as drafts': '풀 리퀘스트를 초안으로 만들기',
  'Turn off Minimal composer to always show the full composer. Tool activity controls whether commands, edits and searches start open or folded. Tool call details show output and full inputs only when enabled. The screen stays on only while you have a running task open.':
    '전체 메시지 입력란을 항상 표시하려면 간소화된 메시지 입력란을 끄세요. 도구 활동에서는 명령, 수정 및 검색을 처음에 펼쳐 둘지 접어 둘지 설정합니다. 도구 호출 세부정보를 켜면 출력과 전체 입력값이 표시됩니다. 실행 중인 작업이 열려 있을 때만 화면이 켜져 있습니다.',
  'Collapse changed files by default': '변경된 파일 기본적으로 접기',
  'Tool activity': '도구 활동',
