    '큰 텍스트, Threads와 설정만 표시, 도구 세부 정보가 없는 채팅. 작업 실행 중에는 화면이 켜져 있습니다. Threads의 자동차 버튼에서도 사용할 수 있습니다. 받아쓰기를 사용하고 도로에 집중하세요.',
