  'Optional URL fields: title, repositoryId, agentId. Requests wait on this phone while offline.':
    '선택적 URL 필드: title, repositoryId, agentId. 오프라인 상태에서는 요청이 이 휴대폰에서 대기합니다.',
  'Discard device host draft?': '기기 호스트 초안을 버릴까요?',
