  'Saved on {value0}. Discover and control simulators and connected phones on other paired computers over SSH.':
    '{value0}에 저장됨. SSH를 통해 다른 페어링된 컴퓨터의 시뮬레이터와 연결된 휴대폰을 검색하고 제어합니다.',
  'the current runtime': '현재 런타임',
  'This computer is offline. Reconnect to load or save device hosts. Your draft is kept here.':
    '이 컴퓨터는 오프라인입니다. 기기 호스트를 불러오거나 저장하려면 다시 연결하세요. 초안은 여기에 보관됩니다.',
  'Loading device hosts…': '기기 호스트 로드 중…',
  'Retry device host settings': '기기 호스트 설정 다시 시도',
  'Device Hub': '기기 허브',
  'Enable device discovery and controls on this runtime. Turning it off keeps saved hosts and leaves devices running.':
    '이 런타임에서 기기 검색과 제어를 활성화합니다. 끄더라도 저장된 호스트는 유지되고 기기는 계속 실행됩니다.',
  'Enable Device Hub': '기기 허브 활성화',
  'Remote device hosts': '원격 기기 호스트',
  'The destination requires an updated installed Dovo runtime and an existing pairing. SSH alone does not grant Dovo access.':
    '대상에 업데이트된 Dovo 런타임이 설치되어 있고 기존 페어링이 있어야 합니다. SSH만으로는 Dovo 액세스 권한이 부여되지 않습니다.',
  'No remote device hosts yet. Local devices remain available.':
    '원격 기기 호스트가 아직 없습니다. 로컬 기기는 계속 사용할 수 있습니다.',
  'Add device host': '기기 호스트 추가',
  'Default device host': '기본 기기 호스트',
  'Local runtime (no remote default)': '로컬 런타임(원격 기본값 없음)',
  'Preselects this host in the desktop device picker. The mobile picker shows devices from all reachable hosts.':
    '데스크톱 기기 선택기에서 이 호스트를 미리 선택합니다. 모바일 선택기에는 연결 가능한 모든 호스트의 기기가 표시됩니다.',
  'Remove device host': '기기 호스트 제거',
  'Remove device host?': '기기 호스트를 제거할까요?',
  'This removes the SSH device host configuration from this runtime. The destination pairing and its devices remain intact.':
    '이 런타임에서 SSH 기기 호스트 구성이 제거됩니다. 대상의 페어링과 기기는 그대로 유지됩니다.',
  'Pair a computer to configure its device hosts.':
    '기기 호스트를 설정하려면 컴퓨터를 페어링하세요.',
  'The current runtime connects over SSH to the destination computer. Install an updated Dovo runtime there and pair it with this phone first.':
    '현재 런타임은 SSH를 통해 대상 컴퓨터에 연결합니다. 먼저 대상에 업데이트된 Dovo 런타임을 설치하고 이 휴대폰과 페어링하세요.',
  'Device host name': '기기 호스트 이름',
  'Paired destination computer': '페어링된 대상 컴퓨터',
  'Keep saved pairing': '저장된 페어링 유지',
  'Choose a paired computer': '페어링된 컴퓨터 선택',
