    '대상의 저장된 페어링을 안전하게 사용합니다. 페어링 토큰은 여기에 표시되지 않습니다.',
  'Destination runtime address': '대상 런타임 주소',
  'HTTP and HTTPS are supported. Use an address reachable from the current runtime. If the address differs from your saved profile, choose the pairing for that same destination.':
    'HTTP와 HTTPS를 지원합니다. 현재 런타임에서 연결할 수 있는 주소를 사용하세요. 주소가 저장된 프로필과 다르면 같은 대상의 페어링을 선택하세요.',
  'SSH host': 'SSH 호스트',
