  'SSH user': 'SSH 사용자',
  'SSH port': 'SSH 포트',
  'SSH identity file path (optional)': 'SSH 신원 파일 경로(선택 사항)',
  'This key path belongs to the current runtime computer, not this phone or the destination. Leave it empty for the runtime’s SSH defaults. Key authentication only; never paste or upload a private key.':
    '이 키 경로는 이 휴대폰이나 대상이 아닌 현재 런타임 컴퓨터의 경로입니다. 런타임의 기본 SSH 설정을 사용하려면 비워 두세요. 키 인증만 지원합니다. 개인 키를 붙여 넣거나 업로드하지 마세요.',
  'Allow agent access': '에이전트 액세스 허용',
