  'Reset all later {value0} overrides': '이후의 {value0} 재정의 모두 초기화',
  'Use inherited {value0}{value1}': '상속된 {value0}{value1} 사용',
  'Set up CuaDriver on this runtime host. CuaDriver owns OS permissions; Dovo connects agents through MCP.':
    '이 런타임 호스트에서 CuaDriver를 설정하세요. CuaDriver는 OS 권한을 관리하고, Dovo는 MCP를 통해 에이전트를 연결합니다.',
  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    '셸 따옴표 없이 호스트 실행 파일 이름 또는 경로를 입력하세요. 에이전트 재정의가 우선 적용됩니다. 새 터미널에는 이 셸 설정이 사용됩니다.',
  'Loading {value0} settings…': '{value0} 설정 불러오는 중…',
