    '이 TURN 서버를 사용하고 릴레이 자격 증명을 이 컴퓨터의 페어링된 클라이언트와 공유할까요? 자동 릴레이 정책이 대체됩니다.',
  'Confirm relay settings': '릴레이 설정 확인',
